import {ToolRegistry} from './registry.js';

describe('ToolRegistry static validation', () => {
  it('reuses the registered static schema across ten executions (spec: specs/hal-engine-tool-input-validation/spec.md#6)', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const executed: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'weather',
        description: 'Weather for a location',
        get inputSchema() {
          schemaReads += 1;
          return {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
        },
      },
      async input => {
        executed.push(input);
        return 'sunny';
      }
    );
    const readsAtRegistration = schemaReads;
    for (let call = 0; call < 10; call += 1) {
      await registry.execute('weather', {location: 'Berlin'});
    }
    expect({readsAtRegistration, schemaReads, executed}).toEqual({
      readsAtRegistration: 1,
      schemaReads: 1,
      executed: Array.from({length: 10}, () => ({location: 'Berlin'})),
    });
  });
});
EOF
